// ================= BHIM ENCYCLOPEDIA LOGIC =================
let activeBhimPillarId = 1;

function renderBhimPillarButtons() {
    const container = document.getElementById('bhim-pillar-pills-container');
    if (!container) return;

    let html = '';
    BHIM_ENC.forEach(p => {
        const isActive = p.id === activeBhimPillarId;
        const btnClass = isActive 
            ? 'bg-amber-500 text-cosmic-900 font-bold border border-amber-400 shadow-md shadow-amber-500/20' 
            : 'bg-cosmic-800 text-slate-300 hover:text-amber-400 hover:bg-cosmic-700 border border-slate-700/60';
        
        let shortTitle = p.title.split('(')[0].trim();
        if (shortTitle.length > 22) shortTitle = shortTitle.substring(0, 20) + '...';

        html += `
            <button onclick="selectBhimPillar(${p.id})" id="bhim-btn-${p.id}" class="px-3.5 py-2 rounded-xl text-xs font-semibold whitespace-nowrap transition-all duration-200 shrink-0 font-hindi ${btnClass}">
                स्तंभ ${p.id}: ${shortTitle} (50 वाक्य)
            </button>
        `;
    });
    container.innerHTML = html;
}

function selectBhimPillar(pillarId) {
    activeBhimPillarId = pillarId;
    renderBhimPillarButtons();
    const pillar = BHIM_ENC.find(p => p.id === pillarId);
    if (pillar) {
        renderBhimPillarSentences(pillar);
    }
}

function renderBhimPillarSentences(pillar) {
    const container = document.getElementById('bhim-pillar-content');
    if (!container) return;

    let html = `
        <div class="glass-card rounded-2xl p-6 space-y-4 border border-amber-500/20">
            <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-3 border-b border-amber-500/20 pb-4">
                <div>
                    <span class="text-xs px-2.5 py-1 rounded-full bg-amber-500/20 text-amber-300 font-semibold border border-amber-500/30">
                        भीम स्तंभ ${pillar.id} / 20
                    </span>
                    <h3 class="text-xl font-bold text-white font-cinzel mt-2">${pillar.title}</h3>
                    <p class="text-xs text-amber-300/80 font-hindi mt-1"><strong>ज्योतिषीय आधार:</strong> ${pillar.astro_basis}</p>
                </div>
                <div class="shrink-0">
                    <span class="px-3 py-1.5 rounded-lg bg-cosmic-800 border border-amber-500/30 text-xs font-bold text-amber-400 font-cinzel">
                        50 अद्वितीय वाक्य
                    </span>
                </div>
            </div>

            <div class="space-y-3 pt-2">
    `;

    pillar.sentences.forEach((s, idx) => {
        html += `
            <div class="sentence-item p-3.5 rounded-xl bg-cosmic-800/40 border border-slate-700/40 hover:border-amber-500/30 transition-all">
                <div class="flex items-start gap-3">
                    <span class="w-6 h-6 rounded-full bg-amber-500/20 text-amber-400 text-xs font-bold flex items-center justify-center shrink-0 mt-0.5 font-cinzel">${idx + 1}</span>
                    <p class="text-sm text-slate-200 font-hindi leading-relaxed">${s}</p>
                </div>
            </div>
        `;
    });

    html += `
            </div>
        </div>

        <div class="flex justify-between items-center pt-4">
            <button onclick="navigateBhimPillar(-1)" class="px-4 py-2 rounded-xl bg-cosmic-800 border border-amber-500/30 text-amber-400 hover:bg-amber-500/10">
                ← पिछला स्तंभ
            </button>
            <span class="text-xs text-slate-400 font-hindi">स्तंभ ${pillar.id} / 20 (कुल 1,000 अद्वितीय वाक्य)</span>
            <button onclick="navigateBhimPillar(1)" class="px-4 py-2 rounded-xl bg-cosmic-800 border border-amber-500/30 text-amber-400 hover:bg-amber-500/10">
                अगला स्तंभ →
            </button>
        </div>
    `;

    container.innerHTML = html;
}

function navigateBhimPillar(direction) {
    let nextId = activeBhimPillarId + direction;
    if (nextId < 1) nextId = 20;
    if (nextId > 20) nextId = 1;
    selectBhimPillar(nextId);
}

// ================= BHIM 500 QUALITIES DIRECT LIST LOGIC =================
function renderBhim500DirectList() {
    const container = document.getElementById('bhim-points-container');
    if (!container) return;

    let html = '';
    BHIM_500.forEach(domain => {
        html += `
            <div class="glass-card rounded-2xl p-6 space-y-4 mb-6 border border-amber-500/20">
                <div class="flex items-center gap-3 border-b border-amber-500/20 pb-3">
                    <span class="text-2xl">${domain.icon}</span>
                    <div>
                        <h3 class="text-lg md:text-xl font-bold text-amber-400 font-cinzel">${domain.title}</h3>
                        <p class="text-xs text-amber-300/70 font-hindi mt-0.5"><strong>ज्योतिषीय आधार:</strong> ${domain.astroBasis}</p>
                    </div>
                </div>
                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
        `;

        domain.points.forEach(p => {
            html += `
                <div class="point-card p-4 rounded-xl bg-cosmic-800/60 border border-slate-700/50 hover:border-amber-500/40 transition-all">
                    <div class="flex items-start gap-3">
                        <span class="w-7 h-7 rounded-full bg-amber-500/20 text-amber-400 text-xs font-bold flex items-center justify-center shrink-0 mt-0.5 font-cinzel">${p.num}</span>
                        <div>
                            <h4 class="text-sm font-bold text-white font-hindi">${p.title}</h4>
                            <p class="text-xs text-slate-300 mt-1.5 font-hindi leading-relaxed">${p.desc}</p>
                        </div>
                    </div>
                </div>
            `;
        });

        html += `
                </div>
            </div>
        `;
    });

    container.innerHTML = html;
}

// Initialize on page load
document.addEventListener('DOMContentLoaded', () => {
    renderBhimPillarButtons();
    if (BHIM_ENC.length > 0) {
        renderBhimPillarSentences(BHIM_ENC[0]);
    }
    renderBhim500DirectList();
});
